class Solution {
  private static final long MOD = 1_000_000_007L;
  private long[] sum, squares, lazy;

  public int sumCounts(int[] nums) {
    int n = nums.length;
    sum = new long[4 * n];
    squares = new long[4 * n];
    lazy = new long[4 * n];
    Map<Integer, Integer> last = new HashMap<>();
    long answer = 0;
    for (int i = 0; i < n; i++) {
      // a new copy of nums[i] adds one distinct value to every subarray starting after its previous
      // copy
      int from = last.getOrDefault(nums[i], -1) + 1;
      add(1, 0, n - 1, from, i, 1);
      last.put(nums[i], i);
      answer = (answer + squares[1]) % MOD;
    }
    return (int) answer;
  }

  private void add(int node, int lo, int hi, int l, int r, long delta) {
    if (r < lo || hi < l) return;
    if (l <= lo && hi <= r) {
      apply(node, hi - lo + 1, delta);
      return;
    }
    push(node, lo, hi);
    int mid = (lo + hi) >>> 1;
    add(2 * node, lo, mid, l, r, delta);
    add(2 * node + 1, mid + 1, hi, l, r, delta);
    sum[node] = (sum[2 * node] + sum[2 * node + 1]) % MOD;
    squares[node] = (squares[2 * node] + squares[2 * node + 1]) % MOD;
  }

  // add delta to every counter in the node's range: (c + d)^2 = c^2 + 2cd + d^2
  private void apply(int node, int length, long delta) {
    squares[node] =
        (squares[node] + 2 * delta % MOD * sum[node] + delta * delta % MOD * length) % MOD;
    sum[node] = (sum[node] + delta * length) % MOD;
    lazy[node] = (lazy[node] + delta) % MOD;
  }

  private void push(int node, int lo, int hi) {
    if (lazy[node] == 0) return;
    int mid = (lo + hi) >>> 1;
    apply(2 * node, mid - lo + 1, lazy[node]);
    apply(2 * node + 1, hi - mid, lazy[node]);
    lazy[node] = 0;
  }
}
